#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_CHUNK_SIZE 4096
#define MAX_CHUNKS 16
#define HEADER_MAGIC 0xCAFEBABE

typedef struct {
    uint32_t magic;
    int32_t num_chunks;  /* signed: from network */
    uint32_t total_size;
} packet_header_t;

typedef struct {
    int32_t chunk_len;   /* signed: from network */
    uint8_t chunk_type;
    uint8_t reserved[3];
} chunk_header_t;

typedef struct {
    uint8_t *data;
    size_t capacity;
    size_t used;
} output_buffer_t;

/* Validates the packet header fields */
static int validate_header(const packet_header_t *hdr) {
    if (hdr->magic != HEADER_MAGIC) return -1;
    if (hdr->num_chunks <= 0 || hdr->num_chunks > MAX_CHUNKS) return -1;
    if (hdr->total_size > (MAX_CHUNKS * MAX_CHUNK_SIZE + sizeof(packet_header_t))) return -1;
    return 0;
}

/* Validates individual chunk parameters */
static int validate_chunk(const chunk_header_t *chdr, int remaining_input) {
    /* Check chunk_len is not larger than max allowed */
    if (chdr->chunk_len > MAX_CHUNK_SIZE) return -1;
    /* Check we have enough input remaining */
    if (chdr->chunk_len > remaining_input) return -1;
    /* Check chunk type is valid */
    if (chdr->chunk_type > 3) return -1;
    return 0;
}

/* Allocates output buffer with exact needed capacity */
static output_buffer_t *alloc_output(size_t capacity) {
    output_buffer_t *buf = calloc(1, sizeof(output_buffer_t));
    if (!buf) return NULL;
    buf->data = calloc(1, capacity);
    if (!buf->data) { free(buf); return NULL; }
    buf->capacity = capacity;
    buf->used = 0;
    return buf;
}

/* Appends chunk data to output buffer with bounds checking */
static int append_chunk_data(output_buffer_t *out, const uint8_t *src, int32_t len) {
    /* Bounds check: ensure we don't exceed capacity */
    if (out->used + len > out->capacity) {
        return -1;
    }
    memcpy(out->data + out->used, src, len);
    out->used += len;
    return 0;
}

/* Transform chunk based on type */
static void transform_chunk(uint8_t *data, size_t len, uint8_t chunk_type) {
    size_t i;
    switch (chunk_type) {
        case 0: break; /* raw */
        case 1: /* XOR obfuscation */
            for (i = 0; i < len; i++) data[i] ^= 0xAA;
            break;
        case 2: /* byte reversal */
            for (i = 0; i < len / 2; i++) {
                uint8_t tmp = data[i];
                data[i] = data[len - 1 - i];
                data[len - 1 - i] = tmp;
            }
            break;
        case 3: /* increment */
            for (i = 0; i < len; i++) data[i]++;
            break;
    }
}

/*
 * Main packet processing function.
 * Parses a binary packet with header + chunks, validates each chunk,
 * and assembles transformed output.
 */
int process_packet(const uint8_t *input, size_t input_len) {
    const packet_header_t *hdr;
    const uint8_t *cursor;
    int remaining;
    int i;
    output_buffer_t *output;

    if (!input || input_len < sizeof(packet_header_t)) return -1;

    hdr = (const packet_header_t *)input;
    if (validate_header(hdr) != 0) return -1;

    /* Allocate output for worst case */
    output = alloc_output(MAX_CHUNKS * MAX_CHUNK_SIZE);
    if (!output) return -1;

    cursor = input + sizeof(packet_header_t);
    remaining = (int)(input_len - sizeof(packet_header_t));

    for (i = 0; i < hdr->num_chunks; i++) {
        const chunk_header_t *chdr;

        if (remaining < (int)sizeof(chunk_header_t)) goto fail;

        chdr = (const chunk_header_t *)cursor;
        cursor += sizeof(chunk_header_t);
        remaining -= sizeof(chunk_header_t);

        /* Validate this chunk's parameters */
        if (validate_chunk(chdr, remaining) != 0) goto fail;

        /* Append validated chunk data to output */
        if (append_chunk_data(output, cursor, chdr->chunk_len) != 0) goto fail;

        /* Apply transformation in-place on output */
        if (chdr->chunk_len > 0) {
            transform_chunk(output->data + output->used - chdr->chunk_len,
                          chdr->chunk_len, chdr->chunk_type);
        }

        cursor += chdr->chunk_len;
        remaining -= chdr->chunk_len;
    }

    printf("Processed %zu bytes of output from %d chunks\n", output->used, hdr->num_chunks);
    free(output->data);
    free(output);
    return 0;

fail:
    free(output->data);
    free(output);
    return -1;
}

int main(void) {
    /* Construct a test packet */
    uint8_t packet[256];
    packet_header_t *hdr = (packet_header_t *)packet;
    chunk_header_t *chdr;

    hdr->magic = HEADER_MAGIC;
    hdr->num_chunks = 1;
    hdr->total_size = sizeof(packet_header_t) + sizeof(chunk_header_t) + 16;

    chdr = (chunk_header_t *)(packet + sizeof(packet_header_t));
    chdr->chunk_len = 16;
    chdr->chunk_type = 1;
    memset(chdr->reserved, 0, 3);
    memset(packet + sizeof(packet_header_t) + sizeof(chunk_header_t), 'A', 16);

    process_packet(packet, sizeof(packet_header_t) + sizeof(chunk_header_t) + 16);
    return 0;
}
